$baselinePath=Join-Path $inputRoot 'baseline.json';Write-StreetTrackedNew01 $baselinePath @{schema=1;kind='StreetTrackedHistoricalBaseline01';currentInstallationVerified=$false;approvalGranted=$false;originalPathsFollowed=$false;gameRoot=$game;gameExecutable=@{sha256=('a'*64);bytes=1};rph=@{sha256=('b'*64);bytes=1};observedApi=@{sha256=('c'*64);historicalOriginAuthenticated=$false};startupSnapshot=(Pin $snapshot);rphIniSnapshot=(Pin $ini);launcherSnapshot=(Pin $launcher);startupPolicy=@{normalMainModMustRemainUnloaded=$true;noRphIniChangeProposed=$true};quarantine=@{originalAbsent=$true;modificationAllowed=$false;held=(Pin $held)};launch=@{method='Windows-shell-open-existing-cmd-once';useShellExecute=$true;verb='open';arguments='';alternateLaunchOrRetry=$false;fileName=(Join-Path $game 'Launch RAGE Plugin Hook.cmd');workingDirectory=$game}}
function Candidate([string]$Name){New-StreetTrackedCandidate01 -BuildReceipt $buildPath -ReviewedBuildReceiptSha256 (Get-StreetTrackedHash01 $buildPath) -HistoricalBaseline $baselinePath -ReviewedBaselineSha256 (Get-StreetTrackedHash01 $baselinePath) -OutputRoot (Join-Path $root $Name)}
function Approval([string]$Candidate){@{approved=$true;kind='RichAudioStreetTrackedSessionApproval01';candidateSha256=(Get-StreetTrackedHash01 $Candidate);supervisorSha256=(Get-StreetTrackedHash01 (Join-Path $repo 'tools/Watch-StreetTrackedSession01.ps1'));maximumLaunches=1;noRetry=$true;processLifetimePinAcknowledged=$true;processExitBeforeRestoration=$true}}
