Check ($plan.approvalGranted-eq$false-and$plan.currentInstallationVerified-eq$false-and$plan.currentActivation-eq$false-and$plan.proposedSessionSidecarEnabled-eq$true) 'Preparation cannot claim installed verification, approval or activation'
