Check ([IO.File]::ReadAllText($startup)-ceq$startupText-and(Get-StreetTrackedHash01 $main)-ceq$mainSha) 'Reviewed restoration returns original startup/main state'
foreach($p in $plan.payload|Where-Object relative -NE 'startup.rphs'){Check (!(Test-Path -LiteralPath (Join-Path $game $p.relative))) 'Only exact introduced diagnostic addition removed'}
$failure=Candidate 'candidate-copy-failure';$failureSha=Get-StreetTrackedHash01 $failure
Reject {Invoke-StreetTrackedTransaction01 -Candidate $failure -ExpectedCandidateSha256 $failureSha -Approval (Approval $failure) -AssertProcessClosure {$true} -AssertFreshInventory {$true} -CopyPayload {param($from,$to)Copy-Item -LiteralPath $from -Destination $to -Force;if([IO.Path]::GetFileName($to)-ceq'RichAudio.StreetTrackedDiagnostic01.json'){throw 'authored injected partial copy failure'}}} 'Injected partial deployment must trigger existing exact rollback'
