foreach($p in $plan.payload|Where-Object relative -NE 'startup.rphs'){Check (!(Test-Path -LiteralPath (Join-Path $game $p.relative))) 'Partial diagnostic additions removed after failure'}
$rollback=Get-Content -LiteralPath (Join-Path (Split-Path $failure -Parent) 'transaction/failure-restoration.json') -Raw|ConvertFrom-Json
